// Decode 按 Type 把 Data 解析为对应的类型（指针，如 *MessageSent）；不认识的类型返回 ErrUnknownEventType。
func (e *Event) Decode() (any, error) {
	var d any
	switch e.Type {
	case "user.created":
		d = new(UserCreated)
	case "user.status_changed":
		d = new(UserStatusChanged)
	case "user.profile_changed":
		d = new(UserProfileChanged)
	case "user.mute_changed":
		d = new(UserMuteChanged)
	case "user.session_created":
		d = new(UserSessionCreated)
	case "user.sessions_revoked":
		d = new(UserSessionsRevoked)
	case "user.relogin_required":
		d = new(UserReloginRequired)
	case "presence.changed":
		d = new(PresenceChanged)
	case "friend.added":
		d = new(FriendAdded)
	case "friend.removed":
		d = new(FriendRemoved)
	case "friend.updated":
		d = new(FriendUpdated)
	case "friend_request.received":
		d = new(FriendRequestReceived)
	case "friend_request.declined":
		d = new(FriendRequestDeclined)
	case "blacklist.changed":
		d = new(BlacklistChanged)
	case "group.created":
		d = new(GroupCreated)
	case "group.info_changed":
		d = new(GroupInfoChanged)
	case "group.dismissed":
		d = new(GroupDismissed)
	case "group.members_added":
		d = new(GroupMembersAdded)
	case "group.members_removed":
		d = new(GroupMembersRemoved)
	case "group.members_updated":
		d = new(GroupMembersUpdated)
	case "group.request_created":
		d = new(GroupRequestCreated)
	case "group.request_handled":
		d = new(GroupRequestHandled)
	case "message.sent":
		d = new(MessageSent)
	case "message.recalled":
		d = new(MessageRecalled)
	case "message.edited":
		d = new(MessageEdited)
	case "chatroom.created":
		d = new(ChatroomCreated)
	case "chatroom.dismissed":
		d = new(ChatroomDismissed)
	case "chatroom.info_changed":
		d = new(ChatroomInfoChanged)
	case "chatroom.members_muted":
		d = new(ChatroomMembersMuted)
	case "chatroom.members_unmuted":
		d = new(ChatroomMembersUnmuted)
	case "chatroom.members_kicked":
		d = new(ChatroomMembersKicked)
	case "chatroom.members_banned":
		d = new(ChatroomMembersBanned)
	case "chatroom.members_unbanned":
		d = new(ChatroomMembersUnbanned)
	case "chatroom.allowlist_changed":
		d = new(ChatroomAllowlistChanged)
	case "chatroom.attributes_changed":
		d = new(ChatroomAttributesChanged)
	case "chatroom.message_sent":
		d = new(ChatroomMessageSent)
	case "chatroom.message_recalled":
		d = new(ChatroomMessageRecalled)
	case "rtc.call_created":
		d = new(RtcCallCreated)
	case "rtc.call_answered":
		d = new(RtcCallAnswered)
	case "rtc.member_joined":
		d = new(RtcMemberJoined)
	case "rtc.member_left":
		d = new(RtcMemberLeft)
	case "rtc.call_ended":
		d = new(RtcCallEnded)
	case "moderation.item_created":
		d = new(ModerationItemCreated)
	case "moderation.item_decided":
		d = new(ModerationItemDecided)
	case "moderation.report_created":
		d = new(ModerationReportCreated)
	case "moderation.violation_recorded":
		d = new(ModerationViolationRecorded)
	case "media.file_uploaded":
		d = new(MediaFileUploaded)
	case "media.file_blocked":
		d = new(MediaFileBlocked)
	case "media.file_unblocked":
		d = new(MediaFileUnblocked)
	case "ai.message_received":
		d = new(AIMessageReceived)
	case "ai.stream_finished":
		d = new(AIStreamFinished)
	case "ai.stream_stopped":
		d = new(AIStreamStopped)
	case "rtc_channel.created":
		d = new(RTCChannelCreated)
	case "rtc_channel.updated":
		d = new(RTCChannelUpdated)
	case "rtc_channel.closing":
		d = new(RTCChannelClosing)
	case "rtc_channel.closed":
		d = new(RTCChannelClosed)
	case "rtc_channel.session_joined":
		d = new(RTCChannelSessionJoined)
	case "rtc_channel.session_leaving":
		d = new(RTCChannelSessionLeaving)
	case "rtc_channel.session_left":
		d = new(RTCChannelSessionLeft)
	case "rtc_channel.member_banned":
		d = new(RTCChannelMemberBanned)
	case "rtc_channel.member_unbanned":
		d = new(RTCChannelMemberUnbanned)
	default:
		return nil, ErrUnknownEventType
	}
	if err := json.Unmarshal(e.Data, d); err != nil {
		return nil, err
	}
	return d, nil
}

